arguments.command:
for b in rachel monica phoebe joey chandler ross; do
  echo "===== $b =====";
  git -C /tmp/ross-main-worktree log --reverse --format='%cI %H' origin/friend/$b | grep -B? no;
  git -C /tmp/ross-main-worktree log --reverse --format='%cI %H %s' origin/friend/$b | grep 'S07/E15';
done

cd /tmp/ross-main-worktree && git pull? ; git fetch origin main && git reset --hard origin/main >/dev/null 2>&1; python3 - <<'PY'
import subprocess,re,glob
commits=[]
for b in ['rachel','monica','phoebe','joey','chandler','ross']:
    out=subprocess.check_output(['git','log','--format=%H%x1f%cI%x1f%B%x1e',f'origin/friend/{b}'], text=True)
    for rec in out.split('\x1e'):
        rec=rec.strip('\n')
        if not rec: continue
        parts=rec.split('\x1f',2)
        sha,ci,body=parts[0],parts[1],parts[2]
        if re.search(r'^Friend-Message:\s*1\s*$', body, re.M):
            m=re.search(r'^Episode:\s*(\S+)\s*$', body, re.M)
            ep=m.group(1) if m else '?'
            commits.append((sha,ep))
srcs=set()
for p in glob.glob('S*/*.md'):
    for line in open(p):
        m=re.match(r'Source:\s*(friend/\S+)\s*@\s*([0-9a-f]+)',line.strip())
        if m: srcs.add(m.group(2))
missing=[c for c in commits if c[0] not in srcs]
print('true commits:',len(commits),'missing:',len(missing))
for m in missing: print(m)
PY
